	record GdbAndTrace(GdbAndConnection conn, ManagedDomainObject<Trace> mdo) : AutoCloseable {
		public void execute(string cmd) {
			conn.execute(cmd);
		}

		public string executeCapture(string cmd) {
			return conn.executeCapture(cmd);
		}

		/* @Override */
		public void close()
    {
			Exception toThrow = null;
			try {
				conn.close();
			}
			catch (Exception e) {
				toThrow = e;
			}
			try {
				mdo.close();
			}
			catch (Exception e) {
				toThrow = e;
			}
			if (toThrow != null) {
				throw toThrow;
			}
		}
	}

	/* @SuppressWarnings("resource") */
	protected GdbAndTrace startAndSyncGdb()
    {
		GdbAndConnection conn = startAndConnectGdb();
		try {
			// TODO: Why does using 'set arch' cause a hang at quit?
			conn.execute("""
					set ghidra-language x86:LE:64:default
					ghidra trace start
					ghidra trace sync-enable""");
			ManagedDomainObject<Trace> mdo = waitTrace("/New Traces/gdb/noname");
			tb = new ToyDBTraceBuilder(mdo.get());
			return new GdbAndTrace(conn, mdo);
		}
		catch (Exception e) {
			conn.close();
			throw e;
		}
	}

	/* @Test */
	public void testOnNewInferior()
